import * as stylex from '@stylexjs/stylex';
export const styles = stylex.create({
  dyn: (w, h) => ({
  color: w * 2,
  rowGap: {
    default: '',
    "@media screen and (max-width: 400px)": w > 10 ? '2px' : '1px'
  },
  "--dyn": w * 2,
  borderTopColor: '#ff0000'
}),
  plain: {
    borderStartColor: {
      default: 'red',
      "@media (prefers-color-scheme: dark)": {
        default: 'rgb(1, 2, 3)',
        ":disabled": 'currentColor'
      }
    },
    width: 'calc(10+pi)',
    "::first-line": {
      flexShrink: 1
    }
  }
});
export const probe = stylex.props(styles.dyn(10), styles.plain);
